		private static int GetPokemonParamIndex(global::Pml.PokeParty party, global::Pml.PokePara.PokemonParam org) {
            uint id = org.GetID();
            uint personalRnd = org.GetPersonalRnd();
            // 02c3d720: GetMemberCount re-read every pass, unsigned compare (b.hs)
            for (uint i = 0; i < party.GetMemberCount(); i++)
            {
                var pp = party.GetMemberPointerConst(i);
                if (pp.GetID() == id && pp.GetPersonalRnd() == personalRnd)
                    return (int)i;
            }
            return -1;
        }
		private static void SetTrainerWinFlag(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM bsp) {
            if (bsp.competitor != BtlCompetitor.BTL_COMPETITOR_TRAINER)
                return;
            var trData = bsp.tr_data;
            if (trData == null)
                return;
            for (int i = 0; i < trData.Length; i++)
            {
                if ((i == (int)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1 || i == (int)BTL_CLIENT_ID.BTL_CLIENT_ENEMY2) && trData[i] != null)
                    TrainerWork.SetWinFlag(trData[i].GetTrainerID());
            }
        }
		private static void ReflectTokuseiMonohiroiMitsuatsume(global::Pml.PokeParty pMyParty) {
            uint count = pMyParty.GetMemberCount();
            for (uint i = 0; i < count; i++)
            {
                var pp = pMyParty.GetMemberPointer(i);
                if (pp.GetMonsNo() == MonsNo.NULL || pp.IsEgg(EggCheckType.BOTH_EGG) || pp.GetItem() != 0)
                    continue;

                if (pp.GetTokuseiNo() == TokuseiNo.MONOHIROI && UnityEngine.Random.Range(0, 100) < 10)
                    pp.SetItem((ushort)GetMonohiroiItem(pp.GetLevel()));

                // 02c3d270: int roll vs uint (level + 1) / 2 compared in 64 bits
                if (pp.GetTokuseiNo() == TokuseiNo.MITUATUME && UnityEngine.Random.Range(1, 101) <= (pp.GetLevel() + 1) / 2)
                    pp.SetItem((ushort)ItemNo.AMAIMITU);
            }
        }
