		public static global::BattleSetupEffectLot GetBattleSetupEffectLot(global::Dpr.Battle.Logic.BtlRule rule, global::Dpr.Battle.Logic.BtlCompetitor competitor = (global::Dpr.Battle.Logic.BtlCompetitor)(0), global::Dpr.Battle.Logic.BtlMultiMode multiMode = (global::Dpr.Battle.Logic.BtlMultiMode)(0), global::Dpr.Trainer.TrainerID trainerID0 = (global::Dpr.Trainer.TrainerID)(707), global::Dpr.Trainer.TrainerID trainerID1 = (global::Dpr.Trainer.TrainerID)(707)) {
            if (competitor == BtlCompetitor.BTL_COMPETITOR_TRAINER || competitor == BtlCompetitor.BTL_COMPETITOR_INST)
            {
                // 02c3b500: both trainer types are looked up before the rule test
                TrainerType type0 = trainerID0 == TrainerID.MAX ? TrainerType.INVALID : TrainerSystem.GetTrainerData(trainerID0).TypeID;
                TrainerType type1 = trainerID1 == TrainerID.MAX ? TrainerType.INVALID : TrainerSystem.GetTrainerData(trainerID1).TypeID;
                if (rule == BtlRule.BTL_RULE_SINGLE)
                    return BattleSetupEffectLot.TR_SINGLE;
                if (multiMode == BtlMultiMode.BTL_MULTIMODE_NONE)
                    return BattleSetupEffectLot.TR_DOUBLE1;
                if (multiMode == BtlMultiMode.BTL_MULTIMODE_P_AA)
                    return TrainerSystem.GetTagTrainerType(type0, type1) == TrainerType.INVALID ? BattleSetupEffectLot.TR_DOUBLE2 : BattleSetupEffectLot.TR_DOUBLE3;
                if (multiMode == BtlMultiMode.BTL_MULTIMODE_PA_AA)
                    return BattleSetupEffectLot.TR_MULTI;
                return BattleSetupEffectLot.WILD_SINGLE;
            }
            if (competitor == BtlCompetitor.BTL_COMPETITOR_WILD && rule != BtlRule.BTL_RULE_SINGLE)
                return rule == BtlRule.BTL_RULE_DOUBLE ? BattleSetupEffectLot.WILD_MULTI : BattleSetupEffectLot.WILD_SAFARI;
            return BattleSetupEffectLot.WILD_SINGLE;
        }
		public static global::Dpr.Trainer.TrainerID GetDemoCaptureTrainer(bool isPlayerMale, global::DPData.DefaultPokeType defaultPokeType) {
            if (defaultPokeType == DefaultPokeType.MIZU)
                return isPlayerMale ? TrainerID.HEROINE_02 : TrainerID.HERO_02;
            if (defaultPokeType == DefaultPokeType.KUSA)
                return isPlayerMale ? TrainerID.HEROINE_03 : TrainerID.HERO_03;
            return isPlayerMale ? TrainerID.HEROINE_01 : TrainerID.HERO_01;
        }
		public static global::Pml.PokeParty CreateDemoCapturePokeParty(global::Dpr.Trainer.TrainerID trainerID) {
            var trainerData = TrainerSystem.GetTrainerData(trainerID);
            var trainerType = TrainerSystem.GetTrainerType(trainerData.TypeID);
            var trainerPoke = TrainerSystem.GetTrainerPoke(trainerID);
            var pokeData = new TrainerSystem.PokeParamForCreate();
            pokeData.Setup(trainerPoke, 0);
            pokeData.Level = 5;   // 02c3b3ac: strb #5 at +5 of the struct
            var pp = TrainerSystem.createPokemon(in pokeData, trainerData, trainerType, null);
            pp.SetDefaultWaza();
            var party = new PokeParty();
            party.AddMember(pp);
            return party;
        }
		private static global::Pml.ItemNo GetMonohiroiItem(uint level) {
            if (level - 1 > 99)
                return ItemNo.DUMMY_DATA;

            // 02c3d800: the table array is held in a register for the whole method
            var monoHiroi = GameData.DataManager.MonohiroiTable.MonoHiroi;
            int index = (byte)(level - 1) / 10;
            int total = monoHiroi[monoHiroi.Length - 1].Ratios[index];
            int rnd = UnityEngine.Random.Range(0, total);
            int sum = 0;
            ItemNo item = ItemNo.DUMMY_DATA;
            for (int i = 0; i < monoHiroi.Length - 1; i++)
            {
                sum += monoHiroi[i].Ratios[index];
                if (rnd < sum)
                {
                    item = monoHiroi[i].ID;
                    break;
                }
            }
            if (sum > total)
            {
                UnityEngine.Debug.LogError("Monohiroi Error");
                return ItemNo.DUMMY_DATA;
            }
            return item;
        }
		public static global::Pml.PokePara.PokemonParam CreateFixPokeParam(global::Pml.MonsNo monsNo, ushort level, uint hp, ushort sex, ushort seikaku, global::Pml.PokePara.Sick sick, ulong random, byte talentVNum) {
            // 02c3d9a0: csel lo (clamp to 100) + csinc on the ORIGINAL level (0 -> 1)
            ushort lv = level;
            if (lv > 100)
                lv = 100;
            if (level == 0)
                lv = 1;

            var spec = new InitialSpec();
            spec.monsno = monsNo;
            spec.level = lv;
            spec.sex = sex;
            spec.seikaku = seikaku;
            spec.personalRnd = random;
            spec.randomSeed = random;
            spec.isRandomSeedEnable = true;
            spec.talentVNum = talentVNum;
            var pp = new PokemonParam(spec);

            if (hp == 0)
                hp = 1;
            else if (pp.GetMaxHp() <= hp)
                hp = pp.GetMaxHp();
            pp.SetHp(hp);
            pp.SetSick(sick);
            return pp;
        }
