		public static void SetupBattleComm(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM bsp, global::INL1.IlcaNetSessionNetworkType networkType, global::Dpr.EncountTools.CommRule commRule, byte commPos, in global::Dpr.Regulation.Data regulation, int stationIndex0, global::Pml.PokeParty party0, in global::MYSTATUS_COMM mystatus0, global::Dpr.BallDeco.CapsuleData[] capsuleDatas0, int stationIndex1, global::Pml.PokeParty party1, in global::MYSTATUS_COMM mystatus1, global::Dpr.BallDeco.CapsuleData[] capsuleDatas1, int stationIndex2 = -1, global::Pml.PokeParty party2 = null, in global::MYSTATUS_COMM mystatus2 = default, global::Dpr.BallDeco.CapsuleData[] capsuleDatas2 = default, int stationIndex3 = -1, global::Pml.PokeParty party3 = null, in global::MYSTATUS_COMM mystatus3 = default, global::Dpr.BallDeco.CapsuleData[] capsuleDatas3 = default, string bgm = null, string winBgm = null, uint GameLimitSec = 1200u, uint CommandLimitSec = 60u) {
            bsp.Clear();
            var situation = new BTL_FIELD_SITUATION();
            Setup.BATTLE_SETUP_FIELD_SITUATION_Init(situation);
            situation.bgComponent.SetUpBgComponentData(ArenaID.G046);   // 02c3db60: mov w1, #0x2b

            // 02c3db78: a null party local passed by `in` (the real parties are copied in by setupPlayerInfo)
            PokeParty playerParty = null;
            BtlCommMode commMode = networkType == IlcaNetSessionNetworkType.Internet ? BtlCommMode.BTL_COMM_WIFI : BtlCommMode.BTL_COMM_WIRELESS;
            Setup.BATTLE_SETUP_Comm(bsp, in playerParty, situation, commMode, commPos);

            setupPlayerInfo(bsp, 0, stationIndex0, party0, in mystatus0, capsuleDatas0);
            setupPlayerInfo(bsp, 1, stationIndex1, party1, in mystatus1, capsuleDatas1);
            if (stationIndex2 >= 0)
                setupPlayerInfo(bsp, 2, stationIndex2, party2, in mystatus2, capsuleDatas2);
            if (stationIndex3 >= 0)
                setupPlayerInfo(bsp, 3, stationIndex3, party3, in mystatus3, capsuleDatas3);

            BtlRule rule;
            BattleSetupEffectId setupEffectId;
            if (commRule == CommRule.Double)
            {
                rule = BtlRule.BTL_RULE_DOUBLE;
                setupEffectId = BattleSetupEffectId.COMM_DOUBLE;
            }
            else if (commRule == CommRule.Multi)
            {
                Setup.BATTLE_SETUP_ToMultiMode(bsp);
                rule = BtlRule.BTL_RULE_DOUBLE;
                setupEffectId = BattleSetupEffectId.COMM_MULTI;
            }
            else
            {
                rule = BtlRule.BTL_RULE_SINGLE;
                setupEffectId = BattleSetupEffectId.COMM_NORMAL;
            }
            bsp.rule = rule;
            bsp.btlEffComponent.SetUpBattleEffectComponentData(setupEffectId, EffectBattleID.NONE, 0, null);
            Setup.BATTLE_PARAM_SetRegulation(bsp, in regulation);
            Setup.BATTLE_PARAM_SetTimeLimit(bsp, GameLimitSec, 0, CommandLimitSec);
            if (!string.IsNullOrEmpty(bgm))
                bsp.btlEffComponent.battleBgm = bgm;
            if (!string.IsNullOrEmpty(winBgm))
                bsp.btlEffComponent.winBgm = winBgm;
            Dpr.Battle.Logic.Net.Client.SetupNetworkCb();
            Dpr.Battle.Logic.Net.Client.RegisterSetupStationIndices(stationIndex0, stationIndex1, stationIndex2, stationIndex3);
        }
		private static void setupPlayerInfo(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM bsp, int index, int stationIndex, global::Pml.PokeParty party, in global::MYSTATUS_COMM mystatus, global::Dpr.BallDeco.CapsuleData[] capsuledata) {
            bsp.stations[index] = stationIndex;
            bsp.playerStatus[index].Deserialize(in mystatus);
            bsp.party[index].CopyFrom(party);
            for (int i = 0; i < bsp.ballDecoDesc[index].Length; i++)
                bsp.ballDecoDesc[index][i].Clear();

            if (capsuledata != null)
            {
                for (int i = 0; i < capsuledata.Length; i++)
                    bsp.ballDecoDesc[index][i].CopyFrom(in capsuledata[i]);
            }

            if (INL1.IlcaNetSession.ThisStationIndex() == stationIndex)
            {
                // 02c3dfe8: no null test on capsuledata here (a null array with a matching station throws, shipped)
                BallDecoWork.ClearTempAttachCapsuleFlags();
                for (int i = 0; i < capsuledata.Length; i++)
                    BallDecoWork.SetTempAttachCapsuleFlag(i, capsuledata[i].AttachPokemonId != 0);
            }
        }
		public static global::System.Collections.IEnumerator DispErrorCoroutine(int commError, bool isDisplayedError) {
            var errorCode = Dpr.Battle.Logic.Net.Client.GetErrorDialogCode(commError);
            var lastErrorCode = Dpr.NetworkUtils.NetworkManager.GetShowApplicationErrorCodeID();
            while (Dpr.NetworkUtils.NetworkManager.IsShowApplicationErrorDialog())
                yield return null;

            if (isDisplayedError || errorCode == Dpr.NetworkUtils.ErrorCodeID.NUM || errorCode == lastErrorCode)
                yield break;

            Dpr.NetworkUtils.NetworkManager.ShowApplicationErrorDialog(errorCode, null);
            while (Dpr.NetworkUtils.NetworkManager.IsShowApplicationErrorDialog())
                yield return null;
        }
